-- ═══════════════════════════════════════════════════════════════
-- 0067: stock flag + the sub-Rs300 Havells variants, listed OUT OF STOCK.
--
-- 1. products.in_stock. Everything already listed stays true; these new rows
--    come in false. An out-of-stock product is still browsable, indexable and
--    price-tracked - it simply cannot be added to the cart (enforced on the
--    server in the order path, not just hidden in the UI).
--
-- 2. 112 variants that Havells sells in families we already stock
--    (motor-run capacitors, low-amperage MCBs and the like). They were absent
--    only because of the Rs300 import floor, so they are added here at our
--    usual Havells-minus-2% and flagged out of stock, plus their exact
--    PARENT::CHILD mapping so the radar tracks them from day one.
-- ═══════════════════════════════════════════════════════════════

alter table public.products add column if not exists in_stock boolean not null default true;
comment on column public.products.in_stock is
  'false = visible and price-tracked, but cannot be ordered (checkout rejects it).';
create index if not exists products_in_stock_idx on public.products (in_stock);

on conflict (id) do update set in_stock = excluded.in_stock, elume_price = excluded.elume_price, mrp = excluded.mrp, hsn = excluded.hsn, gst_rate = excluded.gst_rate;

on conflict (id) do update set in_stock = excluded.in_stock, elume_price = excluded.elume_price, mrp = excluded.mrp, hsn = excluded.hsn, gst_rate = excluded.gst_rate;

on conflict (product_id, source) do update set competitor_code = excluded.competitor_code, updated_at = now();

on conflict (product_id, source) do update set competitor_code = excluded.competitor_code, updated_at = now();

select count(*) filter (where in_stock) as in_stock,
       count(*) filter (where not in_stock) as out_of_stock
from public.products where is_active;
